// Get hourly aggregates for last 24 hours
msg.url = "http://localhost:5000/api/metrics/history";
msg.method = "GET";
msg.headers = {
  "Accept": "application/json"
};

// Query parameters
msg.payload = {
    hours: 24,      // Last 24 hours
    interval: "hourly"  // Get hourly aggregates
};

// Optional: Get specific sensor
// msg.payload.sensor_id = "Cooling_Tower_1";

return msg;

// Convert history data to chart format
let chartData = [];
let sensors = {};

if (msg.payload.data) {
    msg.payload.data.forEach(reading => {
        if (!sensors[reading.sensor_id]) {
            sensors[reading.sensor_id] = {
                series: reading.equipment_name || reading.sensor_id,
                data: [],
                labels: []
            };
        }

        sensors[reading.sensor_id].data.push(reading.avg_velocity);
        sensors[reading.sensor_id].labels.push(new Date(reading.timestamp));
    });

    // Convert to chart format
    Object.values(sensors).forEach(sensor => {
        chartData.push({
            series: sensor.series,
            data: sensor.data,
            labels: sensor.labels
        });
    });
}

msg.payload = chartData;
return msg;

// Get summary statistics
msg.url = "http://localhost:5000/api/metrics/summary?hours=24";
msg.method = "GET";
msg.headers = {
  "Accept": "application/json"
};

return msg;

// Extract key metrics for dashboard
let dashboard = {};

if (msg.payload.summary) {
    Object.entries(msg.payload.summary).forEach(([sensorId, data]) => {
        dashboard[sensorId] = {
            name: data.equipment_name,
            velocity: {
                current: data.velocity.avg,
                max: data.velocity.max,
                unit: "mm/s"
            },
            temperature: {
                current: data.temperature.avg,
                max: data.temperature.max,
                unit: "°F"
            },
            health: {
                zoneA: data.zone_distribution.A_percent,
                zoneB: data.zone_distribution.B_percent,
                zoneC: data.zone_distribution.C_percent,
                zoneD: data.zone_distribution.D_percent
            },
            status: data.zone_distribution.D_percent > 0 ? "Critical" :
                    data.zone_distribution.C_percent > 10 ? "Warning" :
                    data.zone_distribution.B_percent > 50 ? "Fair" : "Good"
        };
    });
}

msg.payload = dashboard;
return msg;

// Get recent alerts (Zone C and D)
msg.url = "http://localhost:5000/api/metrics/alerts?hours=1&limit=50";
msg.method = "GET";
msg.headers = {
  "Accept": "application/json"
};

return msg;

// Check for new critical alerts
if (msg.payload.alerts && msg.payload.alerts.length > 0) {
    let criticalAlerts = msg.payload.alerts.filter(alert => alert.iso_zone === 'D');

    if (criticalAlerts.length > 0) {
        msg.payload = {
            notification: "CRITICAL VIBRATION ALERT!",
            count: criticalAlerts.length,
            alerts: criticalAlerts
        };
        return [msg, null]; // Send to notification
    }

    // Just warnings
    msg.payload = {
        notification: "Vibration warnings detected",
        count: msg.payload.alerts.length,
        alerts: msg.payload.alerts
    };
    return [null, msg]; // Send to warning handler
}

// No alerts
msg.payload = { notification: "All systems normal" };
return [null, null];
